export const stablecoinFaq=[
 ['What is a stablecoin infrastructure provider?','It supplies one or more components for issuing, holding, moving, accepting, converting or monitoring stablecoins. An issuer, wallet provider, payment operator, blockchain developer and compliance tool perform different jobs. Start with the service and responsible entity, not a general crypto label.'],
 ['Which stablecoin infrastructure provider is best?','The best fit depends on your business model, customer and beneficiary types, currencies, token contracts, networks and payment direction. Compare a complete operating route, including custody, conversion, bank payout, support and reconciliation. Alphabetical listings are not a performance ranking.'],
 ['Are Circle, Bridge, BVNK and Fireblocks interchangeable?','No. Circle has issuer and institutional-access products; Bridge and BVNK provide payment and orchestration products; Fireblocks has wallet operations and payment products including Flow. Select the specific module and contractual scope rather than comparing only the parent brand.'],
 ['Does an on-chain confirmation mean a bank payout is complete?','No. Blockchain confirmation, provider balance credit, conversion, bank submission and beneficiary credit are separate events. Agree which evidence supports each status and when the recipient can actually use the money.'],
 ['Is a stablecoin issuer the same as a development company?','No. Developers can build contracts and applications. Issuance and redemption require a separate operating model, responsible entities, reserve and holder-rights arrangements and the permissions relevant to the activity. Software delivery alone does not supply those responsibilities.'],
 ['Does a reserve attestation equal a full financial audit?','No. Read the report type, reporting entity, asset and liability perimeter, observation date, assurance scope and exclusions. A reserve report at a stated date does not continuously verify all liabilities or guarantee recovery in every situation.'],
 ['Can every stablecoin holder redeem directly with the issuer?','Do not assume so. Rights and access depend on the token, issuing entity, holder category, jurisdiction and applicable terms. Distinguish a direct issuer claim from selling on an exchange or using a payment intermediary, and have appropriate advisers review the relevant rights.'],
 ['Are synthetic dollars and tokenized Treasury products payment stablecoins?','They should not be treated as interchangeable. A synthetic dollar, lending position, savings token or secured note has its own backing, counterparties, withdrawal terms and loss risks. Evaluate treasury exposure separately from funds needed for payments.'],
 ['What should a stablecoin card programme compare?','Separate stablecoin funding, custody, conversion, card issuance, processing, authorisation, clearing, scheme settlement and dispute handling. Confirm where cards can be issued, which users qualify and how refunds are funded; global merchant acceptance does not establish cardholder eligibility.'],
 ['What should a cross-chain payment integration test?','Verify the asset contract and destination network, native or wrapped representation, source event, message or attestation, destination credit and recovery path. Define what happens if one step succeeds while the next is delayed. A cross-chain transfer alone is not evidence of bank delivery.'],
 ['Is Mountain Protocol USDM a new-issuance option?','Its wind-down documentation states that minting was disabled. This directory retains USDM as a legacy reference, not a recommendation for new minting or a continuing rewards arrangement. Existing holders should consult the current wind-down terms.'],
 ['How can FluidRWA help with a shortlist?','Share the payment or issuance job, contracting business, customer types, countries, currencies, token/network pairs and integration constraints. Use the same requirements brief for each candidate and ask for production scope, exceptions and evidence before committing.']
];
const section=(id,kicker,title,body)=>`<section class="bc-section sc-section" id="${id}"><div class="light-container"><div class="sc-heading"><p class="eyebrow light-eyebrow">${kicker}</p><h2>${title}</h2></div>${body}</div></section>`;
const table=(caption,headers,rows)=>`<div class="sc-table" role="region" aria-label="${caption}" tabindex="0"><table><caption>${caption}</caption><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((c,i)=>i?`<td>${c}</td>`:`<th scope="row">${c}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const guidance=()=>[
section('stablecoin-job','Start with the outcome','What do you need stablecoins to do?',`<p>The transfer is confirmed on-chain, but the supplier is still waiting for money in its bank account. This is where an attractive payment demo becomes an operating problem. A token transfer completed one step; it did not necessarily complete conversion, compliance review, bank submission or recipient credit.</p><p>Stablecoin infrastructure connects several businesses and systems. The right shortlist makes those boundaries visible. A bank building a branded token needs an issuance model. A marketplace paying sellers needs a payout route. A merchant accepting crypto needs a checkout and settlement process. A treasury team choosing a yield product is making a different risk decision.</p>${table('Match the purchase to the job',['Buyer job','Components to compare','Evidence to request'],[
['Accept a customer payment','Checkout or invoice, wallet address, screening, payment status, conversion and merchant settlement.','A payment journey with late funding, underpayment, refund and reconciliation.'],
['Pay suppliers or marketplace sellers','Business onboarding, funding, liquidity, beneficiary checks and local bank payout.','A named country/currency/rail route and evidence of beneficiary credit or return.'],
['Issue a branded stablecoin','Issuer, reserves, holder terms, contracts, mint/burn control, distribution and redemption.','Entity and responsibility map, reserve reporting and a redemption operating plan.'],
['Embed stablecoins in a fintech','Customer accounts, KYC/KYB, custody, transaction limits, ledger and supported movement.','Approved customer types and a production integration with clear service boundaries.'],
['Operate wallets or a dedicated chain','Signing policies, recovery, gas, sequencing, data availability and incident response.','Control demonstration and exit plan; a separate payment/issuance operating model.'],
['Invest or earn on balances','Asset rights, strategy, credit or derivatives exposure and withdrawal conditions.','Investment and liquidity assessment separate from the payment-services selection.']])}<p>For example, Circle Mint is relevant to institutional issuer access, while Bridge and BVNK describe orchestration and payment services. Fireblocks and Cobo bring wallet or payment-operation components. Chainalysis, Elliptic, TRM Labs and Notabene supply supporting risk tools. These roles can sit in one stack without becoming interchangeable.</p>`),
section('stablecoin-route','Define one complete route','Write the funds flow before the integration brief',`<p>A useful brief names the contracting business, who sends the funds, whose money it is, who receives it and what the recipient needs to receive. Moving your company's treasury, holding merchant proceeds and paying third-party beneficiaries create different requirements. State the customer and beneficiary classes before asking for a list of supported countries.</p><p>Record each currency, token contract, chain ID, wallet model, local payment rail and direction. A provider may support a token on one network but not another. A country may be available for collections but not payouts, or for corporate customers but not individuals. Access to an API endpoint is not confirmation of production approval.</p><h3>Follow the money and the claim</h3><ol><li><strong>Funding:</strong> identify the sender, account owner, deposit instructions and evidence that funds arrived.</li><li><strong>Holding:</strong> name the entity holding fiat, keys or tokens and the customer's legal relationship to that balance.</li><li><strong>Checks:</strong> establish who performs identity, sanctions, transaction and beneficiary checks and who can release a hold.</li><li><strong>Conversion:</strong> record the counterparty, quote validity, execution conditions and what happens after expiry.</li><li><strong>Transfer:</strong> distinguish an internal ledger movement from an actual blockchain transaction.</li><li><strong>Bank payout:</strong> identify who submits the instruction and which partner handles returns or rejection.</li><li><strong>Completion:</strong> define recipient credit and reconcile the customer ledger, chain transaction and bank reference.</li></ol><p>Ask what happens to money held overnight or during a review. A virtual account number does not by itself establish a bank-deposit relationship. An operationally segregated balance, legal segregation and a deposit-protection scheme are different concepts. Have the relevant professionals examine the actual account and safeguarding terms.</p><h3>Illustrative supplier-payment journey</h3><p>A company funds a payment from its own business wallet. The operator checks the deposit, converts under the agreed quote and submits a local-currency bank payout. The company should see separate timestamps and references for deposit acceptance, conversion execution, payout submission and final outcome. If the beneficiary bank rejects the payment, the exception should link back to the original payable rather than create an unexplained new balance.</p><p>This example does not imply that any named provider supports every country or sequence. Use it to ask each shortlisted supplier to show its version of the journey, with the actual counterparties, operating windows and customer communications.</p>`),
section('stablecoin-reserves','Understand the asset','Reserve evidence, redemption rights and liquidity are separate',`<p>A stablecoin ticker is not a complete risk description. Identify the issuer, legal terms, token contract and backing model. Fiat-reserve tokens, crypto-collateralized protocols, synthetic dollars and tokenized investment products can behave differently under stress even when a trading screen shows a similar value.</p><h3>Read the report, not just the badge</h3><p>For a reserve disclosure, record the report type, reporting entity, reporting currency, assets and liabilities included, observation date, publication date, assurance provider and exclusions. A dated attestation is not automatically a full financial-statement audit. A dashboard balance is not a continuous legal or financial guarantee. Do not combine amounts from different dates or entities into a current reserve total.</p><p>Look for the relationship between the reported reserve assets and the token liabilities covered by that report. Ask about cash access, maturity, concentration, custodians, encumbrances and the operational path for liquidating assets. Keep the publication date distinct from the date being measured; a report released today may describe an earlier month-end.</p><h3>Three different ways to exit</h3><ul><li><strong>Issuer redemption:</strong> depends on the relevant issuer terms, holder rights, account eligibility, bank instructions and any review requirements.</li><li><strong>Market sale:</strong> depends on an exchange, broker or liquidity venue, available bids and execution conditions.</li><li><strong>Intermediary payout:</strong> depends on the payment operator's asset acceptance, conversion, banking partners and beneficiary eligibility.</li></ul><p>Do not assume that a token holder can use every route or that an exchange account creates a direct issuer relationship. Equally, do not conclude that a holder has no legal rights merely because they lack a particular portal account. Rights depend on the product and jurisdiction; obtain appropriate advice.</p><h3>Keep payment cash separate from investment exposure</h3><p>Ethena describes USDe as a synthetic dollar. Ondo describes USDY as a tokenized secured note. Maple, Spark, Perena, Sky and Usual have protocol or strategy products with specific risk and withdrawal conditions. Frax's frxUSD and savings/access products also need product-level assessment. Do not sweep customer or near-term operating funds into a strategy merely because the interface calls the balance stable.</p><p>Document who is authorized to take investment risk, who receives any rewards, who bears losses and whether funds can be withdrawn when invoices fall due. Savings, locked positions, lending exposure and derivatives-based strategies are not substitutes for an immediately spendable payment balance.</p>`),
section('stablecoin-control','Own the operating boundary','Custody, contract powers and cross-chain movement',`<p>Key technology and legal custody answer different questions. Multi-party computation can help distribute signing authority, but the actual policy, recovery arrangement and contractual control determine who can move funds. Ask who can change the policy, approve a new address, recover access, replace a signer or suspend an account.</p><p>For a self-custodial model, test whether your team can operate and recover without the service provider. For a custodial model, review account rights, asset segregation, instructions, sub-custodians and an exit process. A connection to a wallet network is not evidence that the provider takes custody, assumes investment risk or guarantees a bank payout.</p><h3>Contract administration matters after launch</h3><p>Identify mint, burn, pause, freeze, blocklist and upgrade powers for the exact contract. Record the people or entities controlling them, approval requirements, emergency authority and audit logs. An audit report should match the code version and deployment scope. A product integrating audited components is not necessarily audited as a complete system.</p><p>For branded issuance, separate developer responsibilities from issuer operations. The delivery agreement should cover source-code ownership, reproducible builds, tests, deployment configuration, administrator handover, monitoring, incident support and change approval. Independently review security scope. A software implementation does not provide reserve assets, banking relationships or issuance permission by itself.</p><h3>Native, wrapped and liquidity-routed transfers</h3><p>Confirm what asset the recipient receives, not just which chain is supported. A native token, wrapped representation and liquidity-swapped token can have different issuers or redemption dependencies. Circle's CCTP materials distinguish asset-specific burn/mint or lock/mint flows, source events, signed attestations and destination completion. The selected version, asset and route determine the mechanism.</p><p>Track the source transaction, message or attestation, destination execution and application credit separately. Define a recovery owner for a successful source action followed by delayed destination execution. Do not initiate a replacement transfer until you know whether the original can still complete.</p><p>For a liquidity-based route, establish inventory ownership, supported pairs, slippage controls, route fallback and unwind responsibility. A fast interface can hide multiple venues or bridges. Chain, bridge, messaging, liquidity and bank dependencies should appear in the incident plan rather than being compressed into one uptime headline.</p>`),
section('stablecoin-cards','Cards and customer experience','Card funding is not card settlement',`<p>A stablecoin-backed card programme combines a funding asset with card issuing and processing. The cardholder may hold tokens, the programme may convert them, and the merchant may receive ordinary card settlement. Specify where conversion occurs and who funds authorisations before settlement is complete.</p><p>Map the card issuer, programme manager, processor, wallet/custodian, conversion provider and network. Ask which cardholders can be onboarded and where cards may be issued. The number of merchants accepting a network is not the number of countries where your programme can issue cards.</p><h3>Test the customer journeys around the purchase</h3><ul><li>Insufficient available balance despite a larger total token balance.</li><li>Authorisation, reversal, partial capture and delayed clearing.</li><li>Refund after the original conversion rate or funding asset changes.</li><li>Disputed payment, chargeback, account restriction and a closed wallet.</li><li>Recurring transactions, expired cards and interrupted customer sessions.</li></ul><p>An irreversible blockchain funding transfer does not remove card-scheme dispute or refund obligations. Agree which party supplies fiat liquidity for reversals and how finance reconciles the original payment, adjustment and customer balance.</p><h3>Merchant acceptance needs its own design</h3><p>A merchant checkout should show the accepted asset, network, deposit window, payment status and support contact. Keep invoice, order and transaction references linked. Decide when goods or services may be released and what evidence is sufficient; displaying a transaction hash alone is not a complete fulfilment policy.</p><p>For an illustrative digital-service purchase, the customer funds an invoice, the processor recognizes the accepted deposit and the merchant receives the configured settlement asset. A later refund should follow an approved return process and be recorded against the original order. Do not automatically trust a refund address supplied in a new email or support message.</p>`),
section('stablecoin-compliance','Jurisdiction and responsibility','Check the entity, the activity and the actual permission',`<p>Start with the regulated activity, not a badge beside a group logo. A token issuer, custodian, money transmitter, payment institution, software vendor and analytics supplier have different roles. Request the exact contracting entity and identify the entity performing each regulated step, including any banking or payout partner.</p><p>Ask which customer types, countries, currencies and activities the proposed service covers. A registration, conditional approval, licence application, trust-company status and final authorization are not interchangeable. A provider describing itself as global does not settle access for your customer or beneficiary.</p><h3>Current official reference points</h3><ul><li><a href="https://occ.gov/news-issuances/bulletins/2026/bulletin-2026-50.html" rel="noopener noreferrer" target="_blank">OCC Bulletin 2026-50</a>, dated October 21, 2026, describes its GENIUS Act final rule and states an effective date of January 18, 2027. Ask advisers to distinguish the rule's publication, effective date and entity-specific requirements.</li><li><a href="https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica" rel="noopener noreferrer" target="_blank">ESMA's MiCA resources</a> separate issuer and crypto-asset service-provider records. Check the applicable file, legal name, activity and current status rather than treating a white paper or brand reference as blanket approval.</li><li>The <a href="https://www.hkma.gov.hk/eng/key-functions/international-financial-centre/stablecoin-issuers/" rel="noopener noreferrer" target="_blank">HKMA stablecoin issuer resources</a> link to its issuer register and supervision guidance. A reserve custodian or trust-company connection is not a substitute for checking the stablecoin issuer itself.</li></ul><p>These references are starting points for professional review, not a legal determination that a listed vendor or token is eligible for your project. Recheck the actual permissions and terms when onboarding and when the product or route changes.</p><h3>Allocate checks before funds arrive</h3><p>Specify who collects customer and beneficial-owner information, who decides onboarding, who screens addresses, who monitors transactions, who exchanges required Travel Rule data and who investigates alerts. Your platform, wallet provider and payout operator may each have separate obligations.</p><p>Define what happens when a deposit arrives before a review finishes or an existing customer becomes ineligible. Keep a controlled escalation process and a lawful return path. A risk-tool response informs the decision; it does not by itself authorize a payment or justify ignoring local obligations.</p><p>Limit personal data in analytics, logs and support channels. Give compliance and operations the evidence they need without placing identity documents, bank details or wallet-to-person mappings in public URLs. Agree access controls, retention and partner-data responsibilities before launch.</p>`),
section('stablecoin-exceptions','Plan for the difficult transaction','An exception matrix belongs in every provider comparison',`${table('Payment exceptions and the evidence to keep',['Situation','Required operating answer','Evidence for finance and support'],[
['Unsupported chain or token','Detection, quarantine, recovery feasibility and who may authorize any recovery attempt.','Asset contract, network, deposit address and case owner.'],
['Underpayment, overpayment or late funding','Invoice tolerance, revised quote or return process without silently completing a different order.','Original invoice, accepted deposit and adjustment decision.'],
['Screening or beneficiary hold','Responsible review team, information request, customer message and lawful release/return conditions.','Status history and authorized decision, with controlled access.'],
['Expired conversion quote','Whether execution stops, a new quote needs approval or the asset remains in a balance.','Quote version, expiry, approval and actual execution record.'],
['Bank rejection or return','Re-entry conditions, account validation and how returned funds are credited.','Payout instruction, bank reference and linked return.'],
['Duplicate webhook or timeout','Authoritative status lookup and idempotent handling before any retry.','Event identifiers, order state and replay record.'],
['Chain or upstream partner outage','Pause criteria, fallback eligibility and customer/support ownership.','Incident timeline, dependency and open obligations.'],
['Depeg or unavailable liquidity','Risk limits, conversion restrictions and an approved contingency without assuming redemption at par.','Observed exposure, decision authority and realized outcome.']])}<p>Wrong-network funds can be unrecoverable. Do not advertise recovery merely because a support ticket can be opened. Likewise, do not initiate another payout while the first instruction's outcome is unknown. A timeout is not proof that a transaction failed.</p><p>One customer contact path is helpful, but the contract should still identify downstream responsibilities. Establish escalation contacts, information-sharing boundaries, service windows and how the business exports open cases if a supplier relationship ends.</p>`),
section('stablecoin-engineering','Integration and finance','Make the API agree with the ledger',`<p>Start in the approved sandbox. Verify authentication, scoped credentials, webhook signatures, retry behavior, rate limits, pagination and the authoritative status endpoint. Test duplicated and out-of-order notifications, interrupted sessions and delayed processing. Store a durable order reference and use idempotency according to the provider's actual guarantees.</p><p>A webhook is a notification, not the accounting ledger. Build an explicit state model for pending checks, available balance, conversion, chain execution, bank submission, completed credit, rejection and return. A provider's label of completed must be translated into your own agreed financial meaning.</p><h3>Make reconciliation possible without a support ticket</h3><p>Keep the invoice or payable ID, provider order ID, funding transaction, conversion reference, destination transaction, bank reference, timestamps, original asset amount, delivered amount and adjustments. Distinguish customer liabilities, operating cash, fees, reserved balances and available liquidity. Use accounting advice for the actual entities and transactions rather than inferring treatment from a token symbol.</p><p>Request usable exports for your ERP, treasury management system and financial close. Confirm time zones, cut-off dates, decimal precision, network fees and how refunds or chargebacks appear. Reconcile control totals and individual exceptions; matching only aggregate daily balances can conceal misallocated customer funds.</p><h3>Liquidity and commercial scope</h3><p>Ask which party prefunds each step, which balances may be reused, how limits change and whether a credit facility is separately approved. A blockchain operating continuously does not mean banks, review teams or liquidity counterparties do. Test weekends, holidays and the relevant payment-rail windows.</p><p>Compare implementation, recurring service, transaction processing, conversion, network, banking, support and exit components under the same scope. Ask how pass-through charges and foreign-exchange spreads are presented. Do not compare headline transaction charges while ignoring trapped prefunding or the cost of resolving exceptions.</p><h3>Measure the complete journey</h3><p>Report eligible attempts, accepted funding, completed conversion, confirmed recipient outcomes, holds, returns and failures separately. Measure time distributions for the whole route and its stages, not only the best blockchain transaction. Define the observation period, sample size, exclusions and incident treatment so supplier results can be compared honestly.</p><p>A sandbox demonstrates integration behavior, not real liquidity, bank acceptance or production permission. Any controlled production test needs its own approval, limits and monitoring. Do not move customer funds merely to validate a sales claim.</p>`),
section('stablecoin-rfp','A practical shortlist','Give every provider the same operating brief',`<p>Start with one job, one customer group and a route your team can support. A narrower service with clear obligations and a working return process can be more useful than a large coverage total. Expand only when onboarding, movement, reconciliation and support operate together.</p><ol><li>What exact product and contracting entity serve this flow?</li><li>Are we moving our own funds, merchant proceeds or customer funds?</li><li>Which sender and beneficiary types are eligible?</li><li>Which currencies, token contracts, chains and local rails are approved in each direction?</li><li>Who holds fiat and crypto at every stage, and what rights attach to each balance?</li><li>Who performs and decides KYC/KYB, transaction and beneficiary checks?</li><li>Who supplies conversion, liquidity, prefunding and bank connectivity?</li><li>What is estimated, quoted, authorized, broadcast, submitted and finally credited?</li><li>Which actions can be paused, reversed, retried or recovered?</li><li>How do wrong-network deposits, late funding and bank returns work?</li><li>Which wallet and contract administrator powers exist?</li><li>What evidence connects the customer order, ledger, blockchain and bank outcome?</li><li>How are keys, credentials, personal data and recovery managed?</li><li>What are the deployment, support, change-control and incident boundaries?</li><li>How can we reconcile open obligations, export records and exit the service?</li></ol><p>Retain dated product documents and the written route response with your decision. Revisit the assessment when a provider changes an issuer, partner bank, legal entity, asset contract or product. An integration example and a marketing announcement do not establish that your production account is enabled.</p><div class="sc-action"><h3>Build a requirements-led shortlist</h3><p>Tell us the service, countries, customers, currencies and integration you need.</p><a class="btn btn-primary light-primary" href="/submit-requirement?category=Stablecoin%20Infrastructure&source=stablecoin-directory">Submit stablecoin requirements</a><a class="btn btn-soft" href="/downloads/stablecoin-operating-brief.txt" download>Download operating brief</a><a href="/apply">Apply to be a Vetted Vendor</a></div><p>Complete the stack with <a href="/vendors/fiat-on-off-ramp-providers">fiat ramp providers</a>, <a href="/vendors/crypto-custody-providers">custody services</a> and <a href="/vendors/kyc-aml-providers">KYC and AML tools</a>. For deeper procurement questions, read the <a href="/blog/white-label-crypto-payment-gateway-buyer-guide">crypto payment gateway buyer guide</a> and <a href="/blog/rwa-vendor-due-diligence-checklist">vendor diligence checklist</a>.</p>`)
].join('');
export function enhanceStablecoinCategory(html){
 const root=parse(html),old=new Map(root.querySelectorAll('.bc-company-card').map(n=>[n.id,n]));
 const sorted=[...stablecoinRecords].sort((a,b)=>a[1].localeCompare(b[1],'en'));
 const title='Stablecoin Infrastructure Providers: Payments & Issuance';
 const description='Compare stablecoin providers by role: payments, issuance, wallets and risk tools. Check custody, redemption, bank payouts and integration before shortlisting.';
 root.querySelector('title').set_content(title);
 for(const [selector,value]of [['meta[name="description"]',description],['meta[property="og:title"]',title],['meta[property="og:description"]',description]])root.querySelector(selector)?.setAttribute('content',value);
 const cards=sorted.map(([id,name,role,desc,question])=>{
  if(id==='nowpayments'){
   const client=old.get(id);if(!client)throw new Error('Preserve existing NOWPayments card');
   client.setAttribute('data-stablecoin-role',role);
   client.querySelector('.bc-company-index').set_content('Crypto Payment Gateway and Stablecoin Infrastructure');
   return client.toString();
  }
  const profile=old.get(id)?.querySelector('.bc-profile-link')?.getAttribute('href');
  return `<article class="bc-company-card" id="${id}" data-stablecoin-role="${role}" data-search="${esc(`${name} ${stablecoinRoles[role]} ${desc} ${question}`.toLowerCase())}"><div class="bc-company-top"><div class="bc-company-mark" aria-hidden="true">${esc(name.slice(0,2).toUpperCase())}</div><div><p class="bc-company-index">${stablecoinRoles[role]}</p><h3>${esc(name)}</h3></div></div><p class="bc-desc">${esc(desc)}</p><details class="bc-provider-details"><summary>Questions before shortlisting</summary><p>${esc(question)}</p></details>${profile?.startsWith('/fluidrwa/')?`<a class="bc-profile-link" href="${profile}">View company profile</a>`:`<a class="bc-profile-link" href="/submit-requirement?source=stablecoin-directory&amp;vendor=${encodeURIComponent(name)}">Discuss requirements</a>`}</article>`;
 }).join('');
 root.querySelector('main').set_content(`<section class="light-section-hero" id="stablecoin-buyer-guide"><div class="light-container"><p class="eyebrow light-eyebrow">Payments, issuance and operations</p><h1>Stablecoin Infrastructure Providers</h1><p>Choose a complete money-movement workflow, not just a token or API. Compare the teams that issue, hold, move, convert and monitor stablecoins.</p><p class="sc-updated">Buyer guide updated November 25, 2026</p><div class="hero-actions"><a class="btn btn-primary light-primary" href="#vendor-directory">Explore 35 records A-Z</a><a class="btn btn-soft" href="#stablecoin-rfp">Prepare your brief</a></div><nav class="sc-jump" aria-label="Stablecoin buyer guide"><a href="#stablecoin-job">Choose the service</a><a href="#vendor-directory">Compare providers</a><a href="#stablecoin-reserves">Reserves and redemption</a><a href="#stablecoin-exceptions">Payment exceptions</a><a href="#stablecoin-faq">FAQs</a></nav><p class="sc-note">For payment teams, fintechs, merchants and issuers. Alphabetical listings include supporting tools, treasury protocols and a clearly marked legacy product, not 35 interchangeable payment operators.</p></div></section>${section('vendor-directory','Directory A-Z','Compare the provider and its actual role',`<p class="sc-directory-intro">Separate issuer access, payment execution, wallet operations, risk tools and protocol exposure before you build a shortlist. Product and account eligibility depend on the proposed route.</p><div class="sc-directory-head"></div><label class="bc-search"><span>Search providers and workflows</span><input id="bcSearch" type="search" placeholder="Company, issuance, payout, wallet or redemption" autocomplete="off"></label><p class="bc-count" id="bcCount">Showing 35 records</p><div class="bc-company-grid" id="bcGrid">${cards}</div>`)}${guidance()}${section('stablecoin-faq','Questions buyers ask','Stablecoin infrastructure FAQs',`<div class="bc-faq-list">${stablecoinFaq.map(([q,a])=>`<details class="bc-faq"><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`)}`);
 root.querySelector('.sc-directory-head').setAttribute('class','bc-directory-head sc-directory-head');
 for(const id of ['fireblocks','cobo'])root.querySelector(`#${id}`).setAttribute('data-stablecoin-role','wallet payments');
 root.querySelector('#ripple').setAttribute('data-stablecoin-role','payments issuer');
 root.querySelector('script[type="application/ld+json"]').set_content(JSON.stringify({'@context':'https://schema.org','@graph':[
  {'@type':'CollectionPage','@id':`${url}#webpage`,url,name:title,description,dateModified:'2026-11-25',mainEntity:{'@id':`${url}#providers`},citation:[...new Set(stablecoinRecords.map(r=>r[5]))]},
  {'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:'https://www.fluidrwa.com/'},{'@type':'ListItem',position:2,name:'Web3 Vendors',item:'https://www.fluidrwa.com/web3vendorecosystem'},{'@type':'ListItem',position:3,name:'Stablecoin Infrastructure Providers',item:url}]},
  {'@type':'ItemList','@id':`${url}#providers`,numberOfItems:sorted.length,itemListElement:sorted.map(([id,name],i)=>({'@type':'ListItem',position:i+1,name,url:`${url}#${id}`}))},
  {'@type':'FAQPage',mainEntity:stablecoinFaq.map(([name,text])=>({'@type':'Question',name,acceptedAnswer:{'@type':'Answer',text}}))}
 ]}));
 root.querySelector('#stablecoin-buyer-styles')?.remove();
 root.querySelector('head').insertAdjacentHTML('beforeend',`<style id="stablecoin-buyer-styles">#stablecoin-buyer-guide{padding:150px 0 32px;text-align:center}#stablecoin-buyer-guide h1{font-size:48px;line-height:1.15;max-width:1000px;margin:12px auto 22px}#stablecoin-buyer-guide>.light-container>p{max-width:920px;margin-left:auto;margin-right:auto}#stablecoin-buyer-guide .hero-actions{justify-content:center}.sc-updated,.sc-note{font-size:15px!important;margin:18px auto!important}.sc-jump{display:flex;flex-wrap:wrap;justify-content:center;gap:14px 26px;border-block:1px solid #cbd9e8;padding:20px 0;margin:26px 0}.sc-jump a{font-weight:700}.sc-section{padding:40px 0!important;scroll-margin-top:132px}.sc-section:nth-of-type(even){background:#fff}.sc-section:not(#vendor-directory)>.light-container{max-width:1000px}.sc-section>.light-container>p{margin:0 0 20px;text-align:left}.sc-heading{max-width:930px;margin:0 auto 28px;text-align:center}.sc-heading h2{font-size:32px;line-height:1.25}.sc-section h3{font-size:23px;line-height:1.35;margin:26px 0 12px}.sc-section p,.sc-section li{line-height:1.75}.sc-directory-intro{max-width:920px;margin:0 auto 24px!important;text-align:center!important}.sc-table{overflow-x:auto;border:1px solid #cbd9e8;border-radius:6px;margin:24px 0}.sc-table:focus-visible{outline:3px solid #1769b1}.sc-table table{width:100%;border-collapse:collapse;font-size:15px}.sc-table caption{padding:16px;background:#edf5fb;text-align:left;font-weight:700}.sc-table th,.sc-table td{padding:15px;min-width:175px;border-bottom:1px solid #d7e2ed;vertical-align:top;text-align:left}.sc-table thead th{background:#18486b;color:#fff}.sc-table tbody th{background:#f0f6fa;color:#152942}.sc-table tbody td{background:#fff;color:#25354b}.sc-action{border-top:2px solid #d7b54d;margin-top:28px;padding-top:18px;text-align:center}.sc-action>a{display:inline-block;margin:12px}.sc-section a{text-underline-offset:3px}.sc-section .bc-company-card{min-width:0}.sc-section .bc-company-card h3{font-size:23px;overflow-wrap:anywhere}.sc-section .bc-company-index{line-height:1.5}.sc-section .bc-company-mark{width:82px;height:82px;flex:0 0 82px}.sc-section .bc-company-card details{margin-top:auto}#vendor-directory .bc-directory-head{display:block!important}@media(max-width:700px){#stablecoin-buyer-guide{padding:120px 0 26px}#stablecoin-buyer-guide h1{font-size:36px}.sc-heading h2{font-size:27px}.sc-section{padding:28px 0!important;scroll-margin-top:110px}.sc-table th,.sc-table td{min-width:160px;padding:12px}.sc-section .bc-company-top{align-items:flex-start}.sc-section #nowpayments .bc-company-mark{width:90px!important;flex:0 0 90px!important}}</style>`);
 root.querySelector('#stablecoin-control-styles')?.remove();
 root.querySelector('head').insertAdjacentHTML('beforeend',`<style id="stablecoin-control-styles">#vendor-directory .vendor-procurement-panel{padding:24px;gap:16px 24px;border-radius:8px;background:#fff;box-shadow:none;backdrop-filter:none;min-height:0}#vendor-directory .vendor-procurement-panel:after{display:none}#vendor-directory .vendor-procurement-intro{display:none}#vendor-directory .vendor-procurement-search{grid-column:1}#vendor-directory .vendor-procurement-filters{grid-column:2;border:0;padding:0;margin:0;align-items:end}#vendor-directory .vendor-procurement-actions{grid-column:1/-1;justify-content:flex-start;flex-wrap:wrap}#vendor-directory .vendor-procurement-actions a{border-radius:6px;background:#edf5fb;color:#155fa7;box-shadow:none;padding:10px 16px}#vendor-directory .vendor-procurement-actions small{max-width:none;text-align:left;color:#52667a;font-size:13px}#vendor-directory .bc-company-card{border-radius:8px;box-shadow:none}@media(max-width:700px){#vendor-directory .vendor-procurement-panel{grid-template-columns:1fr;padding:18px}#vendor-directory .vendor-procurement-search,#vendor-directory .vendor-procurement-filters{grid-column:1}#vendor-directory .vendor-procurement-actions small{flex-basis:100%}}</style>`);
 return root.toString();
}
